package xyz.kd5ujc.scarab.uplc.flat

import xyz.kd5ujc.scarab.codec.{Bytes, Cbor, Node, Value as Cv}
import xyz.kd5ujc.scarab.uplc.PlutusData

/** The CBOR of a `data` value for tests, as the reference's `encodeData` writes small values
  * (`PlutusCore/Data.hs`): constructors 0 to 6 in tags 121 to 127, 7 to 127 in tags 1280 to 1400,
  * others in tag 102; integers beyond 64 bits as big numbers. Byte strings of more than 64 bytes,
  * which the reference writes in chunks, are not generated by the tests that use it.
  */
object DataWriter:
  private val Word = BigInt(1) << 64

  private def node(v: Cv): Node = Node(v, Bytes.empty)

  private def item(d: PlutusData): Cv = d match
    case PlutusData.Constr(i, fs) =>
      val fields = node(Cv.Arr(fs.map(f => node(item(f)))))
      if i >= 0 && i <= 6 then Cv.Tag(121 + i, fields)
      else if i >= 7 && i <= 127 then Cv.Tag(1280 + i - 7, fields)
      else Cv.Tag(102, node(Cv.Arr(Vector(node(Cv.UInt(i)), fields))))
    case PlutusData.Map(kvs) => Cv.Map(kvs.map((k, v) => node(item(k)) -> node(item(v))))
    case PlutusData.List(xs) => Cv.Arr(xs.map(x => node(item(x))))
    case PlutusData.I(n) if n >= 0 && n < Word  => Cv.UInt(n)
    case PlutusData.I(n) if n < 0 && n >= -Word => Cv.NInt(n)
    case PlutusData.I(n) =>
      val magnitude = if n >= 0 then n else -1 - n
      Cv.Tag(
        if n >= 0 then 2 else 3,
        node(Cv.ByteString(Bytes.wrap(magnitude.toByteArray.dropWhile(_ == 0))))
      )
    case PlutusData.B(b) => Cv.ByteString(b)

  def encode(d: PlutusData): Array[Byte] =
    Cbor.encode(item(d)).fold(e => throw IllegalArgumentException(e.message), _.toArray)
